#!/usr/bin/env python3
"""Generate supabase/seed.sql from data/questions.json.

Usage (from the repo root):  python tools/make_seed.py
The generated SQL is idempotent: re-running it updates existing rows.
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
data = json.loads((root / "data" / "questions.json").read_text(encoding="utf-8"))


def lit(s):
    """SQL string literal with single quotes escaped."""
    return "'" + str(s).replace("'", "''") + "'"


out = [
    "-- AZ-900 Smart Quiz (Unofficial) - seed data",
    "-- GENERATED by tools/make_seed.py from data/questions.json. Do not edit by hand.",
    "-- Run in: Supabase Dashboard > SQL Editor, after schema.sql.",
    "",
    "begin;",
    "",
    "insert into public.topics (id, domain, domain_name, domain_weight, name, sort_order, learn_url) values",
]
rows = []
for t in data["topics"]:
    rows.append(
        f"  ({lit(t['id'])}, {t['domain']}, {lit(t['domain_name'])}, {lit(t['domain_weight'])}, "
        f"{lit(t['name'])}, {t['sort_order']}, {lit(t['learn_url'])})"
    )
out.append(",\n".join(rows))
out.append(
    "on conflict (id) do update set domain = excluded.domain, domain_name = excluded.domain_name,\n"
    "  domain_weight = excluded.domain_weight, name = excluded.name,\n"
    "  sort_order = excluded.sort_order, learn_url = excluded.learn_url;"
)
out.append("")
out.append("insert into public.questions (id, topic_id, question, options, correct_index, explanation, difficulty) values")
rows = []
for q in data["questions"]:
    opts = json.dumps(q["options"], ensure_ascii=False)
    rows.append(
        f"  ({lit(q['id'])}, {lit(q['topic'])}, {lit(q['question'])}, {lit(opts)}::jsonb, "
        f"{q['answer']}, {lit(q['explanation'])}, {q['difficulty']})"
    )
out.append(",\n".join(rows))
out.append(
    "on conflict (id) do update set topic_id = excluded.topic_id, question = excluded.question,\n"
    "  options = excluded.options, correct_index = excluded.correct_index,\n"
    "  explanation = excluded.explanation, difficulty = excluded.difficulty;"
)
out.append("")
out.append("commit;")
(root / "supabase" / "seed.sql").write_text("\n".join(out) + "\n", encoding="utf-8")
print(f"Wrote supabase/seed.sql with {len(data['topics'])} topics and {len(data['questions'])} questions")
